"use strict";
const fs = require("node:fs"), path = require("node:path"), crypto = require("node:crypto");
const payload = [{"path":"playwright.social.config.ts","sha256":"cff560644d2a28d5f8cf0c506c675454be085fc6e112af7f59cf9c658f4be52e","base64":""},{"path":"playwright.config.ts","sha256":"6ac49aea8281051d5aabb94f29155680af201a10180b7127847d6275dbfc5aab","base64":""},{"path":"scripts/start-free.cjs","sha256":"f229bad30ab052c1c6bcad14ef5aea2e3fc341d5fc34add4cd3c45cf0658b024","base64":""},{"path":"scripts/build-no-github.cjs","sha256":"7fc3b06ea913ceafdc579d81aa4260ac6056784399500416da653cd11966ee24","base64":""},{"path":"AAB_OLUSTUR.bat","sha256":"28f3bf48ef5c719a7eaac6e75990b06a404f3512726fb889324b11e930c551a2","base64":""}];
const root = process.cwd();
const digest = bytes => crypto.createHash("sha256").update(bytes).digest("hex");
function main() {
  const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
  const app = JSON.parse(fs.readFileSync(path.join(root, "app.json"), "utf8"));
  if (pkg.name !== "birarada-mobile" || app.expo?.android?.package !== "com.birarada.app") throw Error("Bu dosyayi Birarada package.json dosyasinin oldugu klasorde calistir.");
  const files = payload.map(item => {
    if (!/^(playwright(?:\.social)?\.config\.ts|scripts\/(start-free|build-no-github)\.cjs|AAB_OLUSTUR\.bat)$/.test(item.path)) throw Error("Gecersiz guncelleme yolu.");
    const target = path.join(root, ...item.path.split("/"));
    let current = root;
    for (const part of item.path.split("/")) { current = path.join(current, part); if (fs.lstatSync(current).isSymbolicLink()) throw Error("Baglanti dosyalari guncellenmez."); }
    if (!fs.lstatSync(target).isFile()) throw Error("Kaynak dosyasi bulunamadi: " + item.path);
    const bytes = Buffer.from(item.base64, "base64");
    if (digest(bytes) !== item.sha256) throw Error("Guncelleme SHA-256 dogrulamasi basarisiz.");
    return { ...item, target, bytes };
  });
  if (process.argv.includes("--check")) { console.log("Duzeltme ve proje dogrulandi: " + files.length + " dosya. Henuz degisiklik yapilmadi."); return; }
  if (files.every(f => digest(fs.readFileSync(f.target)) === f.sha256)) { console.log("Web baslatma duzeltmesi zaten kurulu."); return; }
  const backup = fs.mkdtempSync(path.join(root, ".birarada-web-backup-"));
  const pending = [], replaced = [];
  try {
    for (const f of files) {
      const saved = path.join(backup, ...f.path.split("/"));
      fs.mkdirSync(path.dirname(saved), { recursive: true }); fs.copyFileSync(f.target, saved);
      const temp = f.target + ".web-fix-" + crypto.randomUUID() + ".tmp";
      fs.writeFileSync(temp, f.bytes, { flag: "wx" }); pending.push({ ...f, temp, saved });
    }
    for (const f of pending) { fs.renameSync(f.temp, f.target); replaced.push(f); }
    console.log("WEB_BASLATMA_DUZELTILDI: " + files.length + " dosya SHA-256 ile dogrulanip guncellendi.");
    console.log("Onceki dosyalarin yedegi: " + path.basename(backup));
    console.log("Sonraki komut: npm run test:social");
  } catch (error) {
    for (const f of replaced.reverse()) { try { fs.copyFileSync(f.saved, f.target); } catch {} }
    throw Error(error.message + " Yedek klasoru: " + backup);
  } finally { for (const f of pending) fs.rmSync(f.temp, { force: true }); }
}
try { main(); } catch (error) { console.error("Duzeltme uygulanamadi: " + error.message); process.exitCode = 1; }
